# If you see that q_list has length=1 but that tensor’s size is (T×D_h,), reshape accordingly.
# For example, if you expect T_batch=10 and D_h=64, but you only see one q_list[0].shape = (640,),
# then do:
#     q_tensor = q_list[0].view(T_batch, D_h)
# Otherwise, if each time‐step was logged separately, do:
q_batch = torch.tensor(batch_q_list, dtype=torch.float32)  # shape = (T, Dh)
k_batch = torch.tensor(batch_k_list, dtype=torch.float32)  # shape = (T, Dh)
v_batch = torch.tensor(batch_v_list, dtype=torch.float32)  # shape = (T, Dh)

q_inc   = torch.tensor(inc_q_list,   dtype=torch.float32)  # shape = (1, Dh) or (T_inc, Dh)
