v_inc   = torch.tensor(inc_v_list,   dtype=torch.float32)  # shape = (T, Dh)

assert q_batch.ndim == 2 and k_batch.ndim == 2 and v_batch.ndim == 2
assert q_inc.ndim == 2 and k_inc.ndim == 2 and v_inc.ndim == 2
Dh = q_batch.size(1)
assert Dh == k_batch.size(1) == v_batch.size(1)
assert Dh == q_inc.size(1) == k_inc.size(1) == v_inc.size(1)
#
# Let Dh = q_batch.size(1)
Dh = q_batch.size(1)
scale = 1.0 / math.sqrt(Dh)

# 3a) Raw scores in batch mode (for all queries). We only care about the last one.
#     scores_batch_full: shape = (T_query, T_key).  But we only need row (T_query - 1).
all_scores_batch = torch.matmul(q_batch, k_batch.transpose(0, 1)) * scale
last_index = q_batch.size(0) - 1  # index of the last query
scores_batch_last = all_scores_batch[last_index]    # shape = (T_keys,)

# 3b) Apply causal mask to “scores_batch_last.”  In a true Transformer, if the query is at index `last_index`,
#     it should only attend to keys [0 .. last_index], and keys (last_index+1 .. T_keys-1) get -inf.

mask = torch.full_like(scores_batch_last, float("-inf"))  # shape = (T_keys,)
# Only keep indices [0 .. last_index]
mask[: last_index + 1] = scores_batch_last[: last_index + 1]
scores_batch_last_masked = mask

# 3c) Softmax( scores_batch_last_masked )
probs_batch_last = torch.softmax(scores_batch_last_masked, dim=0)   # shape = (T_keys,)

# 3d) Weighted sum over V to get “attn_out_batch_last” (one vector of size Dh)
#     v_batch has shape (T_keys, Dh), so:
attn_out_batch_last = torch.matmul(probs_batch_last.unsqueeze(0), v_batch).squeeze(0)
#    → shape = (Dh,)


# ──────── 4) “Manually” recompute the attention for the *incremental* run ────────
#
# In incremental mode, you only have one new query q_inc[0] (shape = Dh),
# but k_inc has shape = (T_keys, Dh) (all the cached keys + this new key),
# and v_inc has shape = (T_keys, Dh).  We compute exactly the same steps:

scores_inc = torch.matmul(q_inc[0], k_inc.transpose(0, 1)) * scale   # shape = (T_keys,)
# Since in incremental mode the “last_index” is also (T_keys-1),
# we apply the same causal mask:
mask_inc = torch.full_like(scores_inc, float("-inf"))
mask_inc[: last_index + 1] = scores_inc[: last_index + 1]
scores_inc_masked = mask_inc

probs_inc = torch.softmax(scores_inc_masked, dim=0)                # shape = (T_keys,)
attn_out_inc_last = torch.matmul(probs_inc.unsqueeze(0), v_inc).squeeze(0)  # shape = (Dh,)


# ──────── 5) Compare “batch vs inc” at every stage ────────
torch.set_printoptions(precision=8, sci_mode=False)

# 5a)  Compare raw scores (before mask)
print("=== BATCH raw scores for query T-1 ===")
print(all_scores_batch[last_index])
print("=== INC  raw scores for the same query  ===")
print(scores_inc)

# 5b) Compare “scores after mask”
print("\n=== BATCH masked scores ===")
print(scores_batch_last_masked)
print("=== INC  masked scores ===")
print(scores_inc_masked)

# 5c) Compare the softmaxed probabilities
print("\n=== BATCH softmax(probs) ===")
print(probs_batch_last)
print("=== INC softmax(probs) ===")
print(probs_inc)

# 5d) Compare the final attended vector
print("\n=== BATCH attn_out (last query) ===")
print(attn_out_batch_last)
print("=== INC   attn_out (last query) ===")
print(attn_out_inc_last)

# 5e) Elementwise difference in final attended vector
diff = (attn_out_batch_last - attn_out_inc_last).abs()
max_diff, max_idx = diff.max(dim=0)
print(f"\nMax |difference| in attended vector = {max_diff.item():.10f}  at index {max_idx.item()}")
print("Batch value at that index:", attn_out_batch_last[max_idx].item())
print("Inc   value at that index:", attn_out_inc_last[max_idx].item())


# 5f) If you want to inspect ULP difference of any particular float32 element,
#    you can reinterpret the floats as uint32 and compare bit patterns:
def float32_to_uint32(f):
    return f.view(dtype=torch.uint32)

batch_bits = float32_to_uint32(attn_out_batch_last)
inc_bits   = float32_to_uint32(attn_out_inc_last)
print("\n=== Bit patterns at the max-difference index ===")
print(f" batch bits = 0x{batch_bits[max_idx].item():08x}")
print(f"   inc bits = 0x{inc_bits[max_idx].item():08x}")
